+async fn sealed_publication(
+    temporary: &TempDir,
+    load: &DeclarationLoad,
+    expected_revision: i64,
+    content_changed: bool,
+) -> anyhow::Result<crate::domain::models::declaration_sync::PreparedPublication> {
+    use crate::domain::{
+        models::declaration_sync::{
+            CompleteDeclarationSnapshot, DeclarationSyncMode, DiscoveryWindow, OwnedDeclaration,
+        },
+        repositories::declaration_sync::DeclarationSyncStorage,
+        services::declaration_sync::{sha256_digest, source_content_digest},
+    };
+    let partition = super::super::declaration_cleaning::read_partition(
+        &temporary
+            .path()
+            .join("data")
+            .join(load.ingestion_key.to_string())
+            .join("raw/declarations/4613.parquet"),
+    )?;
+    let scope = vec![partition.member];
+    let declarations = partition
+        .declarations
+        .into_iter()
+        .map(|evidence| {
+            let declaration = evidence.declaration().clone();
+            (
+                declaration.id(),
+                OwnedDeclaration {
+                    member: partition.member,
+                    declaration,
+                },
+            )
+        })
+        .collect();
+    let date = chrono::NaiveDate::from_ymd_opt(2026, 10, 12).unwrap();
+    let snapshot = CompleteDeclarationSnapshot {
+        schema_version: 1,
+        run: if content_changed {
+            load.ingestion_key.uuid()
+        } else {
+            Uuid::now_v7()
+        },
+        expected_revision,
+        mode: DeclarationSyncMode::Reconcile,
+        source: "test evidence".into(),
+        window: DiscoveryWindow {
+            from: date,
+            through: date,
+        },
+        scope_sha256: sha256_digest(&serde_json::to_vec(&scope)?),
+        scope,
+        pending_members: vec![],
+        exclusions: Default::default(),
+        omissions: vec![],
+        receipts: vec![],
+        artifacts: Default::default(),
+        content_sha256: source_content_digest(&declarations)?,
+        declarations,
+        content_changed,
+        captured_at: Utc::now(),
+    };
+    let root = temporary.path().join(format!("sealed-{}", Uuid::now_v7()));
+    let store = super::super::declaration_sync::DeclarationSnapshotStore::new(&root, 100)?;
+    let publication = store.seal_snapshot(snapshot).await?;
+    Ok(publication)
+}
+
+#[sqlx::test(migrations = "../db/migrations")]
+async fn publication_retry_no_load_and_stale_guards(pool: sqlx::PgPool) -> anyhow::Result<()> {
+    let (temporary, load) = resolved_test_run().await?;
+    sqlx::query!("INSERT INTO exposed.members (parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons) VALUES (4613, 'Test member', 1, 'Test party', 1, 'Test constituency', true)").execute(&pool).await?;
+    let repository = ExposedDatabase::from(pool.clone());
+    let initial = sealed_publication(&temporary, &load, 0, true).await?;
+    sqlx::query!("CREATE FUNCTION exposed.reject_publication() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'injected publication failure'; END $$").execute(&pool).await?;
+    sqlx::query!("CREATE TRIGGER reject_publication BEFORE INSERT ON exposed.declaration_sync_runs FOR EACH ROW EXECUTE FUNCTION exposed.reject_publication()").execute(&pool).await?;
+    let empty = database_snapshot(&pool).await?;
+    assert!(
+        repository
+            .publish_declaration_sync(&initial, Some(&load))
+            .await
+            .is_err()
+    );
+    assert_eq!(database_snapshot(&pool).await?, empty);
+    sqlx::query!("DROP TRIGGER reject_publication ON exposed.declaration_sync_runs")
+        .execute(&pool)
+        .await?;
+    assert!(
+        repository
+            .publish_declaration_sync(&initial, Some(&load))
+            .await?
+    );
+    let before = database_snapshot(&pool).await?;
+    assert!(
+        !repository
+            .publish_declaration_sync(&initial, Some(&load))
+            .await?
+    );
+    assert!(
+        repository
+            .load_declarations(&load)
+            .await
+            .unwrap_err()
+            .to_string()
+            .contains("sync owns the projection")
+    );
+    let stale = sealed_publication(&temporary, &load, 0, false).await?;
+    assert!(
+        repository
+            .publish_declaration_sync(&stale, None)
+            .await
+            .unwrap_err()
+            .to_string()
+            .contains("stale declaration publication base")
+    );
+    let mut false_noop = sealed_publication(&temporary, &load, 1, false).await?;
+    let mut manifest: serde_json::Value =
+        serde_json::from_slice(&fs::read(&false_noop.manifest_path)?)?;
+    manifest["content_sha256"] = json!("different source content");
+    let bytes = serde_json::to_vec(&manifest)?;
+    fs::write(&false_noop.manifest_path, &bytes)?;
+    false_noop.manifest_sha256 = crate::domain::services::declaration_sync::sha256_digest(&bytes);
+    assert!(
+        repository
+            .publish_declaration_sync(&false_noop, None)
+            .await
+            .unwrap_err()
+            .to_string()
+            .contains("unchanged publication content differs")
+    );
+    let unchanged = sealed_publication(&temporary, &load, 1, false).await?;
+    assert!(
+        repository
+            .publish_declaration_sync(&unchanged, None)
+            .await?
+    );
+    assert!(
+        !repository
+            .publish_declaration_sync(&unchanged, None)
+            .await?
+    );
+    assert_eq!(database_snapshot(&pool).await?, before);
+    let revision = sqlx::query_scalar!("SELECT revision FROM exposed.declaration_sync_runs r JOIN exposed.declaration_sync_head h USING (ingestion_key)").fetch_one(&pool).await?;
+    assert_eq!(revision, 2);
+    Ok(())
+}
